mapper.select:
SELECT
    (SELECT IFNULL(SUM(total_price), 0)
     FROM erp_sale_out
     WHERE out_time >= #{beginTime}

           AND out_time < #{endTime}

       AND deleted = 0) -
    (SELECT IFNULL(SUM(total_price), 0)
        FROM erp_sale_return
        WHERE return_time >= #{beginTime}

            AND return_time < #{endTime}

        AND deleted = 0)
